var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VRC.SDK3.Avatars.Components.VRCAvatarDescriptor>(true)).Single(a=>a.name=="MANUKA_lilToon");
var result=new System.Collections.Generic.List<string>();
foreach(float scale in new[]{1f,1.2f}){var a=UnityEngine.Object.Instantiate(original.gameObject);try{a.transform.localScale=UnityEngine.Vector3.one*scale;var r=a.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>().Single(s=>s.name=="Manuka_body");var temp=new UnityEngine.GameObject("measurement");try{temp.transform.SetPositionAndRotation(r.transform.position,r.transform.rotation);temp.transform.localScale=r.transform.lossyScale;var s=temp.AddComponent<UnityEngine.SkinnedMeshRenderer>();s.sharedMesh=r.sharedMesh;s.bones=r.bones;s.rootBone=r.rootBone;foreach(bool useScale in new[]{false,true}){var m=new UnityEngine.Mesh();r.BakeMesh(m,useScale);result.Add(scale+";original;"+useScale+";bounds="+m.bounds);s.BakeMesh(m,useScale);result.Add(scale+";temporary;"+useScale+";bounds="+m.bounds);UnityEngine.Object.DestroyImmediate(m);}}finally{UnityEngine.Object.DestroyImmediate(temp);}}finally{UnityEngine.Object.DestroyImmediate(a);}}
return result;
